def matching(records, rating):
    def quick(a):
        if len(a)<2:return a[:]
        p=a[0][1]
        return quick([x for x in a if x[1]>p])+[x for x in a if x[1]==p]+quick([x for x in a if x[1]<p])
    a=quick(records)
    lo,hi=0,len(a)
    while lo<hi:
        mid=(lo+hi)//2
        if a[mid][1]>rating:lo=mid+1
        else:hi=mid
    start=lo;hi=len(a)
    while lo<hi:
        mid=(lo+hi)//2
        if a[mid][1]>=rating:lo=mid+1
        else:hi=mid
    return sorted(x[0] for x in a[start:lo])
